        $common = @(@{name="vmnic4"}, @{name="vmnic5"})
        $result = InModuleScope VcfEdgeAtScale -ArgumentList $cluster,$common { Get-EffectiveNicListForCluster -Cluster $args[0] -CommonNicList $args[1] }
        $result[0].name | Should -Be "vmnic4"
    }
}

