            $secure = ConvertTo-SecureString -String "super-secret-vcenter-pw" -AsPlainText -Force
            $null = Get-VcenterRestApiPlainPassword -VcenterPassword $secure
            Should -Invoke Write-LogMessage -Times 0
        }
