            { Assert-ArgoCDServiceExists -SupervisorId "sup-1" -Service "argocd-service.vsphere.vmware.com" } | Should -Not -Throw
            Should -Not -Invoke Write-LogMessage -ParameterFilter { $Type -eq 'ERROR' }
