# ── Set-StoragePolicy — contract tests (extraction deferred) ──────────────────

Describe "Resolve-StoragePolicyTagContext" {

    It "Throws when the tag does not exist" {
        InModuleScope VcfEdgeAtScale {
            function Get-Tag {
                [CmdletBinding()] Param([Parameter()] [Object]$Name, [Parameter()] [Object]$Category, [Parameter()] [Object]$Server)
                throw "Tag not found"
            }
            function Get-SpbmStoragePolicy {
                [CmdletBinding()] Param([Parameter()] [Object]$Name, [Parameter()] [Object]$Tag, [Parameter()] [Object]$Server)
                process {}
            }

            {
                Resolve-StoragePolicyTagContext -PolicyName "VMFS-Policy" -Server "vc.lab" -TagCatalog "Environment" -TagName "missing-tag"
            } | Should -Throw "*Tag not found*"

        }
    }

    It "Returns null ExistingPolicy and TagAlreadyPresent=false when policy does not exist" {
        InModuleScope VcfEdgeAtScale {
            $fakeTag = [PSCustomObject]@{ Name = "site1"; Id = "tag-1"; Category = [PSCustomObject]@{ Name = "Site" } }
            function Get-Tag {
                [CmdletBinding()] Param([Parameter()] [Object]$Name, [Parameter()] [Object]$Category, [Parameter()] [Object]$Server)
                $fakeTag
            }
            function Get-SpbmStoragePolicy {
                [CmdletBinding()] Param([Parameter()] [Object]$Name, [Parameter()] [Object]$Tag, [Parameter()] [Object]$Server)
                return $null
            }

            $result = Resolve-StoragePolicyTagContext -PolicyName "VMFS-Policy" -Server "vc.lab" -TagCatalog "Site" -TagName "site1"

            $result.ExistingPolicy   | Should -BeNullOrEmpty
            $result.TagAlreadyPresent | Should -Be $false
            $result.TagObject.Name   | Should -Be "site1"
        }
    }

    It "Returns ExistingPolicy and TagAlreadyPresent=false when policy exists but tag is absent" {
        InModuleScope VcfEdgeAtScale {
            $fakeTag    = [PSCustomObject]@{ Name = "site1"; Id = "tag-1"; Category = [PSCustomObject]@{ Name = "Site" } }
            $fakePolicy = [PSCustomObject]@{ Name = "VMFS-Policy"; AnyOfRuleSets = @() }
            $Script:_spbmContextCount = 0
            function Get-Tag {
                [CmdletBinding()] Param([Parameter()] [Object]$Name, [Parameter()] [Object]$Category, [Parameter()] [Object]$Server)
                $fakeTag
            }
            function Get-SpbmStoragePolicy {
                [CmdletBinding()] Param([Parameter()] [Object]$Name, [Parameter()] [Object]$Tag, [Parameter()] [Object]$Server)
                $Script:_spbmContextCount++
                # First call: existence check (no -Tag) → policy exists.
                # Second call: tag check (with -Tag) → tag absent → null.
                if ($Script:_spbmContextCount -le 1) { return $fakePolicy }
                return $null
            }

            $result = Resolve-StoragePolicyTagContext -PolicyName "VMFS-Policy" -Server "vc.lab" -TagCatalog "Site" -TagName "site1"

            $result.ExistingPolicy.Name  | Should -Be "VMFS-Policy"
            $result.TagAlreadyPresent     | Should -Be $false
        }
    }

    It "Returns TagAlreadyPresent=true when policy exists and tag is already present" {
        InModuleScope VcfEdgeAtScale {
            $fakeTag    = [PSCustomObject]@{ Name = "site1"; Id = "tag-1"; Category = [PSCustomObject]@{ Name = "Site" } }
            $fakePolicy = [PSCustomObject]@{ Name = "VMFS-Policy"; AnyOfRuleSets = @() }
            function Get-Tag {
                [CmdletBinding()] Param([Parameter()] [Object]$Name, [Parameter()] [Object]$Category, [Parameter()] [Object]$Server)
                $fakeTag
            }
            function Get-SpbmStoragePolicy {
                [CmdletBinding()] Param([Parameter()] [Object]$Name, [Parameter()] [Object]$Tag, [Parameter()] [Object]$Server)
                # Both existence check and tag check return the policy.
                return $fakePolicy
            }

            $result = Resolve-StoragePolicyTagContext -PolicyName "VMFS-Policy" -Server "vc.lab" -TagCatalog "Site" -TagName "site1"

            $result.TagAlreadyPresent | Should -Be $true
        }
    }
}
Describe "Set-StoragePolicy — new policy creation paths" {
    # These tests describe Set-StoragePolicy's contract so the extraction to separate
    # lookup/application functions can be done safely. NO extraction should occur until
    # all 5 tests here pass both before and after any refactoring.

    It "Creates a new VMFS storage policy when no policy exists" {
        InModuleScope VcfEdgeAtScale {
            $Script:vCenterName = "vc.lab"
            $fakeTag        = [PSCustomObject]@{ Name = "Production"; Id = "tag-1"; Category = [PSCustomObject]@{ Name = "Environment" } }
            $fakeCapability = [PSCustomObject]@{ Name = "com.vmware.storage.volumeallocation.VolumeAllocationType" }
            $fakeRule       = [PSCustomObject]@{ Capability = $fakeCapability; Value = "Fully initialized" }
            $fakeRuleSet    = [PSCustomObject]@{ AllOfRules = @($fakeRule) }
            $fakePolicy     = [PSCustomObject]@{ Name = "VMFS-Policy"; AnyOfRuleSets = @($fakeRuleSet) }

            function Invoke-VcenterReconnectIfNeeded { [CmdletBinding()] Param() }
            function Get-Tag {
                [CmdletBinding()] Param([Parameter()] [Object]$Name, [Parameter()] [Object]$Category, [Parameter()] [Object]$Server)
                $fakeTag
            }
            $Script:_spbmCallCount = 0
            function Get-SpbmStoragePolicy {
                [CmdletBinding()] Param([Parameter()] [Object]$Name, [Parameter()] [Object]$Tag, [Parameter()] [Object]$Server)
                $Script:_spbmCallCount++
                # First call: existence check → null (policy does not exist yet).
                # Subsequent calls: verification after New-SpbmStoragePolicy → return the policy.
                if ($Script:_spbmCallCount -le 1) { return $null }
                return [PSCustomObject]@{ Name = "VMFS-Policy" }
            }
            function Get-SpbmCapability {
                [CmdletBinding()] Param([Parameter()] [Object]$Name, [Parameter()] [Object]$Server)
                $fakeCapability
            }
            function New-SpbmRule {
                [CmdletBinding()] Param([Parameter()] [Object]$AnyOfTags, [Parameter()] [Object]$Capability, [Parameter()] [Object]$Value, [Parameter()] [Object]$Server)
                $fakeRule
            }
            function New-SpbmRuleSet {
                [CmdletBinding()] Param([Parameter()] [Object]$AllOfRules)
                $fakeRuleSet
            }
            function New-SpbmStoragePolicy {
                [CmdletBinding()] Param([Parameter()] [Object]$Name, [Parameter()] [Object]$Description, [Parameter()] [Object]$AnyOfRuleSets, [Parameter()] [Object]$Server)
                begin {}; process {}
            }

            Mock Write-LogMessage {}

            Set-StoragePolicy -PolicyName "VMFS-Policy" -StorageType "VMFS" -TagName "Production" -TagCatalog "Environment"

            Should -Invoke Write-LogMessage -Scope It -ParameterFilter {
                $Message -like "*Successfully created*VMFS-Policy*"
            }
        }
    }

    It "Creates a new vSAN-ESA policy without a volume allocation rule" {
        InModuleScope VcfEdgeAtScale {
            $Script:vCenterName = "vc.lab"
            $fakeTag     = [PSCustomObject]@{ Name = "Site1"; Id = "tag-2"; Category = [PSCustomObject]@{ Name = "Location" } }
            $fakeRule    = [PSCustomObject]@{ AnyOfTags = @($fakeTag) }
            $fakeRuleSet = [PSCustomObject]@{ AllOfRules = @($fakeRule) }

            $Script:_spbmVsanCallCount = 0
            function Invoke-VcenterReconnectIfNeeded { [CmdletBinding()] Param() }
            function Get-Tag {
                [CmdletBinding()] Param([Parameter()] [Object]$Name, [Parameter()] [Object]$Category, [Parameter()] [Object]$Server)
                $fakeTag
            }
            function Get-SpbmStoragePolicy {
                [CmdletBinding()] Param([Parameter()] [Object]$Name, [Parameter()] [Object]$Tag, [Parameter()] [Object]$Server)
                $Script:_spbmVsanCallCount++
                if ($Script:_spbmVsanCallCount -le 1) { return $null }
                return [PSCustomObject]@{ Name = "vSAN-ESA-Policy" }
            }
            function Get-SpbmCapability {
                # vSAN path must NOT call this — define stub that signals if called.
                [CmdletBinding()] Param([Parameter()] [Object]$Name, [Parameter()] [Object]$Server)
                begin { $Script:_spbmCapCalled = $true }; process {}
            }
            function New-SpbmRule {
                [CmdletBinding()] Param([Parameter()] [Object]$AnyOfTags, [Parameter()] [Object]$Capability, [Parameter()] [Object]$Value, [Parameter()] [Object]$Server)
                $fakeRule
            }
            function New-SpbmRuleSet {
                [CmdletBinding()] Param([Parameter()] [Object]$AllOfRules)
                $fakeRuleSet
            }
            function New-SpbmStoragePolicy {
                [CmdletBinding()] Param([Parameter()] [Object]$Name, [Parameter()] [Object]$Description, [Parameter()] [Object]$AnyOfRuleSets, [Parameter()] [Object]$Server)
                begin {}; process {}
            }

            $Script:_spbmCapCalled = $false
            Mock Write-LogMessage {}

            Set-StoragePolicy -PolicyName "vSAN-ESA-Policy" -StorageType "vSAN-ESA" -TagName "Site1" -TagCatalog "Location"

            # vSAN path must NOT call Get-SpbmCapability (no volume allocation rule).
            $Script:_spbmCapCalled | Should -Be $false
            Should -Invoke Write-LogMessage -Scope It -ParameterFilter {
                $Message -like "*Successfully created*vSAN-ESA-Policy*"
            }
        }
    }

    It "Returns without modification when policy already contains the tag (idempotent)" {
        InModuleScope VcfEdgeAtScale {
            $Script:vCenterName = "vc.lab"
            $fakeTag = [PSCustomObject]@{ Name = "Production"; Id = "tag-1"; Category = [PSCustomObject]@{ Name = "Environment" } }

            function Invoke-VcenterReconnectIfNeeded { [CmdletBinding()] Param() }
            function Get-Tag {
                [CmdletBinding()] Param([Parameter()] [Object]$Name, [Parameter()] [Object]$Category, [Parameter()] [Object]$Server)
                $fakeTag
            }
            function Get-SpbmStoragePolicy {
                [CmdletBinding()] Param([Parameter()] [Object]$Name, [Parameter()] [Object]$Tag, [Parameter()] [Object]$Server)
                # Return a policy object regardless of whether -Tag is specified.
                [PSCustomObject]@{ Name = "VMFS-Policy"; AnyOfRuleSets = @() }
            }

            Mock Write-LogMessage {}

            { Set-StoragePolicy -PolicyName "VMFS-Policy" -StorageType "VMFS" -TagName "Production" -TagCatalog "Environment" } | Should -Not -Throw
            Should -Invoke Write-LogMessage -ParameterFilter { $Type -eq "DEBUG" -and $Message -match "already contains tag" }
        }
    }

    It "Throws VcfDeploymentException on UnauthorizedAccessException" {
        { InModuleScope VcfEdgeAtScale {
            $Script:vCenterName = "vc.lab"

            function Invoke-VcenterReconnectIfNeeded { [CmdletBinding()] Param() }
            function Get-Tag {
                [CmdletBinding()] Param([Parameter()] [Object]$Name, [Parameter()] [Object]$Category, [Parameter()] [Object]$Server)
                throw [System.UnauthorizedAccessException]::new("Access denied")
            }

            Mock Write-LogMessage {}

            Set-StoragePolicy -PolicyName "VMFS-Policy" -StorageType "VMFS" -TagName "Production" -TagCatalog "Environment"
        } } | Should -Throw "*authorization*"
    }

    It "Throws when Invoke-VcenterReconnectIfNeeded fails (session lost and reconnect unsuccessful)" {
        { InModuleScope VcfEdgeAtScale {
            $Script:vCenterName = "vc.lab"
            Mock Write-LogMessage {}
            function Invoke-VcenterReconnectIfNeeded {
                [CmdletBinding()] Param()
                throw [VcfDeploymentException]::new("vCenter session lost and reconnect failed.")
            }
            Set-StoragePolicy -PolicyName "VMFS-Policy" -StorageType "VMFS" -TagName "Production" -TagCatalog "Environment"
        } } | Should -Throw
    }
}

# ── Invoke-MergeTagRules ──────────────────────────────────────────────────────

Describe "Invoke-MergeTagRules" {

    It "Combines the existing tag with the new tag into a single AnyOfTags rule" {
        $result = InModuleScope VcfEdgeAtScale {
            $Script:vCenterName = "vc.lab"
            $existingTag = [PSCustomObject]@{ Name = "site1"; Id = "tag-1"; Category = [PSCustomObject]@{ Name = "Site" } }
            $newTag      = [PSCustomObject]@{ Name = "site2"; Id = "tag-2"; Category = [PSCustomObject]@{ Name = "Site" } }
            $fakeTagRule = [PSCustomObject]@{ AnyOfTags = @($existingTag) }
            $fakeRule    = [PSCustomObject]@{ AnyOfTags = @($existingTag, $newTag) }

            function Get-Tag {
                [CmdletBinding()] Param([Parameter()] [Object]$Name, [Parameter()] [Object]$Category, [Parameter()] [Object]$Server)
                if ($Name -eq "site1") { return $existingTag }
                return $newTag
            }
            function New-SpbmRule {
                [CmdletBinding()] Param([Parameter()] [Object]$AnyOfTags, [Parameter()] [Object]$Capability, [Parameter()] [Object]$Value, [Parameter()] [Object]$Server)
                $fakeRule
            }
            Mock Write-LogMessage {}

            Invoke-MergeTagRules -TagRules @($fakeTagRule) -NewTagObject $newTag -PolicyName "VMFS-Policy"
        }
        $result.AnyOfTags.Count | Should -Be 2
    }

    It "Strips the vSphere '(missing)' suffix and re-fetches the tag by name and category" {
        $fetchedName = InModuleScope VcfEdgeAtScale {
            $Script:vCenterName  = "vc.lab"
            $Script:_fetchedName = $null
            $staleTag    = [PSCustomObject]@{ Name = "site1 (missing)"; Id = $null; Category = [PSCustomObject]@{ Name = "Site (missing)" } }
            $freshTag    = [PSCustomObject]@{ Name = "site1"; Id = "tag-1"; Category = [PSCustomObject]@{ Name = "Site" } }
            $newTag      = [PSCustomObject]@{ Name = "site2"; Id = "tag-2"; Category = [PSCustomObject]@{ Name = "Site" } }
            $fakeTagRule = [PSCustomObject]@{ AnyOfTags = @($staleTag) }
            $fakeRule    = [PSCustomObject]@{ AnyOfTags = @($freshTag, $newTag) }

            function Get-Tag {
                [CmdletBinding()] Param([Parameter()] [Object]$Name, [Parameter()] [Object]$Category, [Parameter()] [Object]$Server)
                $Script:_fetchedName = $Name
                if ($Name -eq "site1") { return $freshTag }
                return $newTag
            }
            function New-SpbmRule {
                [CmdletBinding()] Param([Parameter()] [Object]$AnyOfTags, [Parameter()] [Object]$Capability, [Parameter()] [Object]$Value, [Parameter()] [Object]$Server)
                $fakeRule
            }
            Mock Write-LogMessage {}

            $null = Invoke-MergeTagRules -TagRules @($fakeTagRule) -NewTagObject $newTag -PolicyName "VMFS-Policy"
            $Script:_fetchedName
        }
        # The "(missing)" suffix must be stripped before the Get-Tag call.
        $fetchedName | Should -Be "site1"
    }

    It "Falls back to a new-tag-only rule when all existing tags are entirely stale (empty name after strip)" {
        $result = InModuleScope VcfEdgeAtScale {
            $Script:vCenterName = "vc.lab"
            $ghostTag    = [PSCustomObject]@{ Name = " (missing)"; Id = $null; Category = [PSCustomObject]@{ Name = "Site" } }
            $newTag      = [PSCustomObject]@{ Name = "site2"; Id = "tag-2"; Category = [PSCustomObject]@{ Name = "Site" } }
            $fakeTagRule = [PSCustomObject]@{ AnyOfTags = @($ghostTag) }
            $fallbackRule = [PSCustomObject]@{ AnyOfTags = @($newTag) }

            function Get-Tag {
                [CmdletBinding()] Param([Parameter()] [Object]$Name, [Parameter()] [Object]$Category, [Parameter()] [Object]$Server)
                $newTag
            }
            function New-SpbmRule {
                [CmdletBinding()] Param([Parameter()] [Object]$AnyOfTags, [Parameter()] [Object]$Capability, [Parameter()] [Object]$Value, [Parameter()] [Object]$Server)
                $fallbackRule
            }
            Mock Write-LogMessage {}

            Invoke-MergeTagRules -TagRules @($fakeTagRule) -NewTagObject $newTag -PolicyName "VMFS-Policy"
        }
        # With only the new tag remaining (ghost was skipped), the result should reference site2.
        $result.AnyOfTags[0].Name | Should -Be "site2"
    }

    It "Omits existing tags from a different category (SPBM intra-category requirement)" {
        $tagCount = InModuleScope VcfEdgeAtScale {
            $Script:vCenterName      = "vc.lab"
            $Script:_ruleTagCount    = 0
            $crossCatTag = [PSCustomObject]@{ Name = "prod"; Id = "tag-99"; Category = [PSCustomObject]@{ Name = "Env" } }
            $newTag      = [PSCustomObject]@{ Name = "site1"; Id = "tag-1"; Category = [PSCustomObject]@{ Name = "Site" } }
            $fakeTagRule = [PSCustomObject]@{ AnyOfTags = @($crossCatTag) }

            function Get-Tag {
                [CmdletBinding()] Param([Parameter()] [Object]$Name, [Parameter()] [Object]$Category, [Parameter()] [Object]$Server)
                if ($Name -eq "prod") { return $crossCatTag }
                return $newTag
            }
            function New-SpbmRule {
                [CmdletBinding()] Param([Parameter()] [Object]$AnyOfTags, [Parameter()] [Object]$Capability, [Parameter()] [Object]$Value, [Parameter()] [Object]$Server)
                $Script:_ruleTagCount = if ($AnyOfTags -is [Array]) { $AnyOfTags.Count } else { 1 }
                [PSCustomObject]@{ AnyOfTags = @($newTag) }
            }
            Mock Write-LogMessage {}

            $null = Invoke-MergeTagRules -TagRules @($fakeTagRule) -NewTagObject $newTag -PolicyName "VMFS-Policy"
            $Script:_ruleTagCount
        }
        # Cross-category tag is filtered; only the new tag passes the category check.
        $tagCount | Should -Be 1
    }

    It "Deduplicates tags that appear in both existing rules and the new tag (same ID)" {
        $dedupeTagCount = InModuleScope VcfEdgeAtScale {
            $Script:vCenterName       = "vc.lab"
            $Script:_dedupeTagCount   = 0
            # Existing rule already contains the tag we are adding (same Id).
            $sharedTag   = [PSCustomObject]@{ Name = "site1"; Id = "tag-1"; Category = [PSCustomObject]@{ Name = "Site" } }
            $fakeTagRule = [PSCustomObject]@{ AnyOfTags = @($sharedTag) }

            function Get-Tag {
                [CmdletBinding()] Param([Parameter()] [Object]$Name, [Parameter()] [Object]$Category, [Parameter()] [Object]$Server)
                $sharedTag
            }
            function New-SpbmRule {
                [CmdletBinding()] Param([Parameter()] [Object]$AnyOfTags, [Parameter()] [Object]$Capability, [Parameter()] [Object]$Value, [Parameter()] [Object]$Server)
                $Script:_dedupeTagCount = if ($AnyOfTags -is [Array]) { $AnyOfTags.Count } else { 1 }
                [PSCustomObject]@{ AnyOfTags = @($sharedTag) }
            }
            Mock Write-LogMessage {}

            $null = Invoke-MergeTagRules -TagRules @($fakeTagRule) -NewTagObject $sharedTag -PolicyName "VMFS-Policy"
            $Script:_dedupeTagCount
        }
        # Tag should appear exactly once despite being in both the existing rule and the new tag.
        $dedupeTagCount | Should -Be 1
    }
}

# ── Add-StoragePolicyTagRule ──────────────────────────────────────────────────

Describe "Add-StoragePolicyTagRule" {

    It "Creates a VMFS rule set (capability + tag) when the existing policy has no rule sets" {
        $setSpbmCalled = InModuleScope VcfEdgeAtScale {
            $Script:vCenterName    = "vc.lab"
            $Script:_setSpbmCalled = $false
            $fakeTag        = [PSCustomObject]@{ Name = "site1"; Id = "tag-1"; Category = [PSCustomObject]@{ Name = "Site" } }
            $fakeCapability = [PSCustomObject]@{ Name = "com.vmware.storage.volumeallocation.VolumeAllocationType" }
            $fakeRule       = [PSCustomObject]@{ AnyOfTags = @($fakeTag) }
            $fakeRuleSet    = [PSCustomObject]@{ AllOfRules = @($fakeRule) }
            $fakePolicy     = [PSCustomObject]@{ Name = "VMFS-Policy"; AnyOfRuleSets = @() }

            function Get-SpbmCapability {
                [CmdletBinding()] Param([Parameter()] [Object]$Name, [Parameter()] [Object]$Server)
                $fakeCapability
            }
            function New-SpbmRule {
                [CmdletBinding()] Param([Parameter()] [Object]$AnyOfTags, [Parameter()] [Object]$Capability, [Parameter()] [Object]$Value, [Parameter()] [Object]$Server)
                $fakeRule
            }
            function New-SpbmRuleSet {
                [CmdletBinding()] Param([Parameter()] [Object]$AllOfRules)
                $fakeRuleSet
            }
            function Set-SpbmStoragePolicy {
                [CmdletBinding(SupportsShouldProcess = $true)]
                Param([Parameter()] [Object]$StoragePolicy, [Parameter()] [Object]$AnyOfRuleSets, [Parameter()] [Object]$Server)
                begin { $Script:_setSpbmCalled = $true }; process {}
            }
            Mock Write-LogMessage {}

            Add-StoragePolicyTagRule -PolicyName "VMFS-Policy" -StorageType "VMFS" -RuleValue "Fully initialized" `
                -TagCatalog "Site" -TagName "site1" -Policy $fakePolicy -TagObject $fakeTag
            $Script:_setSpbmCalled
        }
        $setSpbmCalled | Should -Be $true
    }

    It "Creates a vSAN rule set (tag only, no capability) when the existing policy has no rule sets" {
        $Script:_vsanCapCalled = $false
        InModuleScope VcfEdgeAtScale {
            $Script:vCenterName = "vc.lab"
            $fakeTag     = [PSCustomObject]@{ Name = "site1"; Id = "tag-1"; Category = [PSCustomObject]@{ Name = "Site" } }
            $fakeRule    = [PSCustomObject]@{ AnyOfTags = @($fakeTag) }
            $fakeRuleSet = [PSCustomObject]@{ AllOfRules = @($fakeRule) }
            $fakePolicy  = [PSCustomObject]@{ Name = "vSAN-Policy"; AnyOfRuleSets = @() }

            function Get-SpbmCapability {
                [CmdletBinding()] Param([Parameter()] [Object]$Name, [Parameter()] [Object]$Server)
                begin { $Script:_vsanCapCalled = $true }; process {}
            }
            function New-SpbmRule {
                [CmdletBinding()] Param([Parameter()] [Object]$AnyOfTags, [Parameter()] [Object]$Capability, [Parameter()] [Object]$Value, [Parameter()] [Object]$Server)
                $fakeRule
            }
            function New-SpbmRuleSet {
                [CmdletBinding()] Param([Parameter()] [Object]$AllOfRules)
                $fakeRuleSet
            }
            function Set-SpbmStoragePolicy {
                [CmdletBinding(SupportsShouldProcess = $true)]
                Param([Parameter()] [Object]$StoragePolicy, [Parameter()] [Object]$AnyOfRuleSets, [Parameter()] [Object]$Server)
                begin {}; process {}
            }
            Mock Write-LogMessage {}

            Add-StoragePolicyTagRule -PolicyName "vSAN-Policy" -StorageType "vSAN-OSA" -RuleValue "Fully initialized" `
                -TagCatalog "Site" -TagName "site1" -Policy $fakePolicy -TagObject $fakeTag
        }
        # vSAN path must not fetch the volume allocation capability.
        $Script:_vsanCapCalled | Should -Be $false
    }

    It "Skips rule sets with no AllOfRules and logs a WARNING for each skipped set" {
        InModuleScope VcfEdgeAtScale {
            $Script:vCenterName = "vc.lab"
            $fakeTag     = [PSCustomObject]@{ Name = "site1"; Id = "tag-1"; Category = [PSCustomObject]@{ Name = "Site" } }
            $emptyRuleSet = [PSCustomObject]@{ AllOfRules = $null }
            $fakeRule    = [PSCustomObject]@{ AnyOfTags = @($fakeTag) }
            $fakeRuleSet = [PSCustomObject]@{ AllOfRules = @($fakeRule) }
            $fakePolicy  = [PSCustomObject]@{ Name = "VMFS-Policy"; AnyOfRuleSets = @($emptyRuleSet) }

            function Get-SpbmCapability {
                [CmdletBinding()] Param([Parameter()] [Object]$Name, [Parameter()] [Object]$Server)
                [PSCustomObject]@{ Name = "vol-alloc" }
            }
            function New-SpbmRule {
                [CmdletBinding()] Param([Parameter()] [Object]$AnyOfTags, [Parameter()] [Object]$Capability, [Parameter()] [Object]$Value, [Parameter()] [Object]$Server)
                $fakeRule
            }
            function New-SpbmRuleSet {
                [CmdletBinding()] Param([Parameter()] [Object]$AllOfRules)
                $fakeRuleSet
            }
            function Set-SpbmStoragePolicy {
                [CmdletBinding(SupportsShouldProcess = $true)]
                Param([Parameter()] [Object]$StoragePolicy, [Parameter()] [Object]$AnyOfRuleSets, [Parameter()] [Object]$Server)
                begin {}; process {}
            }
            Mock Write-LogMessage {}

            Add-StoragePolicyTagRule -PolicyName "VMFS-Policy" -StorageType "VMFS" -RuleValue "Fully initialized" `
                -TagCatalog "Site" -TagName "site1" -Policy $fakePolicy -TagObject $fakeTag

            # One WARNING logged for the skipped empty rule set; fallback rule set creation follows.
            Should -Invoke Write-LogMessage -Scope It -ParameterFilter { $Type -eq "WARNING" }
        }
    }

    It "Preserves the existing capability rule value when processing a VMFS rule set" {
        $capRuleValue = InModuleScope VcfEdgeAtScale {
            $Script:vCenterName   = "vc.lab"
            $Script:_capRuleValue = $null
            $fakeTag          = [PSCustomObject]@{ Name = "site1"; Id = "tag-1"; Category = [PSCustomObject]@{ Name = "Site" } }
            $fakeCap          = [PSCustomObject]@{ Name = "com.vmware.storage.volumeallocation.VolumeAllocationType" }
            $existingCapRule  = [PSCustomObject]@{ Capability = $fakeCap; Value = "Reserve space"; AnyOfTags = $null }
            $fakeRuleWithTags = [PSCustomObject]@{ AnyOfTags = @($fakeTag) }
            $existingRuleSet  = [PSCustomObject]@{ AllOfRules = @($existingCapRule) }
            $fakePolicy       = [PSCustomObject]@{ Name = "VMFS-Policy"; AnyOfRuleSets = @($existingRuleSet) }
            $fakeRuleSet      = [PSCustomObject]@{ AllOfRules = @($existingCapRule) }

            function Get-SpbmCapability {
                [CmdletBinding()] Param([Parameter()] [Object]$Name, [Parameter()] [Object]$Server)
                $fakeCap
            }
            function New-SpbmRule {
                [CmdletBinding()] Param([Parameter()] [Object]$AnyOfTags, [Parameter()] [Object]$Capability, [Parameter()] [Object]$Value, [Parameter()] [Object]$Server)
                if ($Value) { $Script:_capRuleValue = $Value }
                $fakeRuleWithTags
            }
            function New-SpbmRuleSet {
                [CmdletBinding()] Param([Parameter()] [Object]$AllOfRules)
                $fakeRuleSet
            }
            function Set-SpbmStoragePolicy {
                [CmdletBinding(SupportsShouldProcess = $true)]
                Param([Parameter()] [Object]$StoragePolicy, [Parameter()] [Object]$AnyOfRuleSets, [Parameter()] [Object]$Server)
                begin {}; process {}
            }
            Mock Write-LogMessage {}
            Mock Invoke-MergeTagRules { $fakeRuleWithTags }

            Add-StoragePolicyTagRule -PolicyName "VMFS-Policy" -StorageType "VMFS" -RuleValue "Fully initialized" `
                -TagCatalog "Site" -TagName "site1" -Policy $fakePolicy -TagObject $fakeTag
            $Script:_capRuleValue
        }
        # The existing "Reserve space" value must be used, not the default "Fully initialized".
        $capRuleValue | Should -Be "Reserve space"
    }

    It "Throws VcfDeploymentException with diagnostic message when Set-SpbmStoragePolicy reports invalid format" {
        { InModuleScope VcfEdgeAtScale {
            $Script:vCenterName = "vc.lab"
            $fakeTag     = [PSCustomObject]@{ Name = "site1"; Id = "tag-1"; Category = [PSCustomObject]@{ Name = "Site" } }
            $fakeRule    = [PSCustomObject]@{ AnyOfTags = @($fakeTag) }
            $fakeRuleSet = [PSCustomObject]@{ AllOfRules = @($fakeRule) }
            $fakePolicy  = [PSCustomObject]@{ Name = "VMFS-Policy"; AnyOfRuleSets = @() }

            function Get-SpbmCapability {
                [CmdletBinding()] Param([Parameter()] [Object]$Name, [Parameter()] [Object]$Server)
                [PSCustomObject]@{ Name = "vol-alloc" }
            }
            function New-SpbmRule {
                [CmdletBinding()] Param([Parameter()] [Object]$AnyOfTags, [Parameter()] [Object]$Capability, [Parameter()] [Object]$Value, [Parameter()] [Object]$Server)
                $fakeRule
            }
            function New-SpbmRuleSet {
                [CmdletBinding()] Param([Parameter()] [Object]$AllOfRules)
                $fakeRuleSet
            }
            function Set-SpbmStoragePolicy {
                [CmdletBinding(SupportsShouldProcess = $true)]
                Param([Parameter()] [Object]$StoragePolicy, [Parameter()] [Object]$AnyOfRuleSets, [Parameter()] [Object]$Server)
                begin { throw "Operation failed: invalid format detected" }; process {}
            }
            Mock Write-LogMessage {}

            Add-StoragePolicyTagRule -PolicyName "VMFS-Policy" -StorageType "VMFS" -RuleValue "Fully initialized" `
                -TagCatalog "Site" -TagName "site1" -Policy $fakePolicy -TagObject $fakeTag
        } } | Should -Throw "*Policies and Profiles > VM Storage Policies*"
    }
}

# ── Resolve-DeploymentRootDirectory ──────────────────────────────────────────

Describe "Resolve-DeploymentRootDirectory" {

    It "Returns DefaultBaseDirectory when no env var is set and user presses Enter" {
        $result = InModuleScope VcfEdgeAtScale {
            $env:VcfEdgeAtScaleRootDirectory = $null
            Mock Write-Host {}
            Mock Read-Host { "" }
            Resolve-DeploymentRootDirectory -DefaultBaseDirectory (Join-Path ([System.IO.Path]::GetTempPath()) "VcfEdgeAtScale")
        }
        $result | Should -Be (Join-Path ([System.IO.Path]::GetTempPath()) "VcfEdgeAtScale")
    }

    It "Returns the user-typed path when user provides a custom directory" {
        $result = InModuleScope VcfEdgeAtScale {
            $env:VcfEdgeAtScaleRootDirectory = $null
            Mock Write-Host {}
            Mock Read-Host { "/custom/deployment/root" }
            Resolve-DeploymentRootDirectory -DefaultBaseDirectory (Join-Path ([System.IO.Path]::GetTempPath()) "VcfEdgeAtScale")
        }
        $result | Should -Be "/custom/deployment/root"
    }

    It "Clears the stale env var when it points to a non-existent path and then prompts" {
        $result = InModuleScope VcfEdgeAtScale {
            $env:VcfEdgeAtScaleRootDirectory = "/path/that/does/not/exist/abc123"
            Mock Write-Host {}
            Mock Read-Host { "/fallback/dir" }
            Resolve-DeploymentRootDirectory -DefaultBaseDirectory (Join-Path ([System.IO.Path]::GetTempPath()) "VcfEdgeAtScale")
        }
        $result | Should -Be "/fallback/dir"
        $env:VcfEdgeAtScaleRootDirectory | Should -BeNullOrEmpty
    }

    It "Returns the env var path when it resolves to a fully initialized layout and user accepts" {
        $result = InModuleScope VcfEdgeAtScale {
            $tempDir = [System.IO.Path]::GetTempPath()
            $env:VcfEdgeAtScaleRootDirectory = $tempDir
            Mock Test-VcfEdgeAtScaleDeploymentRootInitialized { $true }
            Mock Write-Host {}
            # User presses Enter (accepts the existing dir)
            Mock Read-Host { "" }
            Resolve-DeploymentRootDirectory -DefaultBaseDirectory (Join-Path ([System.IO.Path]::GetTempPath()) "VcfEdgeAtScale")
        }
        $result | Should -Not -BeNullOrEmpty
    }

    It "Returns the env var path when it resolves to a fully initialized layout and user answers 'n'" {
        $result = InModuleScope VcfEdgeAtScale {
            $tempDir = (Resolve-Path -LiteralPath ([System.IO.Path]::GetTempPath())).Path
            $env:VcfEdgeAtScaleRootDirectory = $tempDir
            Mock Test-VcfEdgeAtScaleDeploymentRootInitialized { $true }
            Mock Write-Host {}
            # Answer "n" to "Initialize a different directory instead?" → keep the current env root
            Mock Read-Host { "n" }
            Resolve-DeploymentRootDirectory -DefaultBaseDirectory (Join-Path ([System.IO.Path]::GetTempPath()) "VcfEdgeAtScale")
        }
        $result | Should -Not -BeNullOrEmpty
    }
}

Describe "Copy-InitializeTemplateFiles — guard paths and copy logic" {

    It "Logs an error and returns false when a required YAML template source file is missing" {
        $result = InModuleScope VcfEdgeAtScale {
            $tempRoot = Join-Path ([System.IO.Path]::GetTempPath()) "veastest-$([System.Guid]::NewGuid().ToString('N'))"
            $null = New-Item -ItemType Directory -Path $tempRoot -Force
            try {
                # TemplatesPath directory exists but has no files — first YAML template will be missing.
                $Script:VcfEdgeAtScaleServiceYamlTemplateFileNames = @("missing-template.yaml")
                Mock Write-Host {}
                Mock Write-LogMessage {}
                $copyResult = Copy-InitializeTemplateFiles `
                    -DocsDirectory         (Join-Path $tempRoot "Docs") `
                    -ServicesYamlDirectory (Join-Path $tempRoot "ServicesYaml") `
                    -TemplateRestoreHint   "Reinstall the module." `
                    -TemplatesPath         $tempRoot `
                    -ToolsDirectory        (Join-Path $tempRoot "Tools")
                Should -Invoke Write-LogMessage -ParameterFilter { $Type -eq "ERROR" -and $Message -match "Required module template is missing" } -Times 1 -Exactly
                return $copyResult
            } finally {
                Remove-Item -LiteralPath $tempRoot -Recurse -Force -ErrorAction SilentlyContinue
            }
        }
        $result | Should -Be $false
    }

    It "Skips the YAML copy when Confirm-FileOverwritePrompt returns false" {
        $copyCount = InModuleScope VcfEdgeAtScale {
            $tempRoot = Join-Path ([System.IO.Path]::GetTempPath()) "veastest-$([System.Guid]::NewGuid().ToString('N'))"
            $null = New-Item -ItemType Directory -Path $tempRoot -Force
            try {
                $Script:VcfEdgeAtScaleServiceYamlTemplateFileNames = @("service.yaml")
                # Create the source YAML template file so the exists-check passes.
                $null = New-Item -ItemType File -Path (Join-Path $tempRoot "service.yaml") -Force
                # Confirm-FileOverwritePrompt → $false simulates user answering N to overwrite.
                Mock Confirm-FileOverwritePrompt { $false }
                Mock Update-HelpJsonIfStale { $false }
                Mock Write-Host {}
                Mock Write-Warning {}
                $Script:_copyCount = 0
                Mock Copy-Item { $Script:_copyCount++ }
                $null = Copy-InitializeTemplateFiles `
                    -DocsDirectory         (Join-Path $tempRoot "Docs") `
                    -ServicesYamlDirectory (Join-Path $tempRoot "ServicesYaml") `
                    -TemplateRestoreHint   "Reinstall the module." `
                    -TemplatesPath         $tempRoot `
                    -ToolsDirectory        (Join-Path $tempRoot "Tools")
                $Script:_copyCount
            } finally {
                Remove-Item -LiteralPath $tempRoot -Recurse -Force -ErrorAction SilentlyContinue
            }
        }
        # No files copied because Confirm returned false for every prompt.
        $copyCount | Should -Be 0
    }
}

# ── Initialize-RootJsonFilesFromTemplate ─────────────────────────────────────

Describe "Initialize-RootJsonFilesFromTemplate — error paths log and return false" {

    It "Logs ERROR and returns false when the infrastructure template file is missing" {
        $result = InModuleScope VcfEdgeAtScale {
            $tmpRoot = Join-Path -Path ([System.IO.Path]::GetTempPath()) -ChildPath "veas-test-$([System.Guid]::NewGuid().ToString('N'))"
            $null = New-Item -ItemType Directory -Path $tmpRoot -Force
            try {
                Mock Write-Host {}
                Mock Write-LogMessage {}
                Initialize-RootJsonFilesFromTemplate `
                    -BaseDirectory                 $tmpRoot `
                    -InfrastructureDestinationPath (Join-Path $tmpRoot "infrastructure.json") `
                    -InfrastructureTemplatePath    (Join-Path $tmpRoot "missing-infra-template.json") `
                    -ServicesYamlDirectory         (Join-Path $tmpRoot "ServicesYaml") `
                    -SupervisorDestinationPath     (Join-Path $tmpRoot "supervisor.json") `
                    -SupervisorTemplatePath        (Join-Path $tmpRoot "missing-super-template.json") `
                    -TemplateRestoreHint           "reinstall hint"
            } finally {
                Remove-Item -LiteralPath $tmpRoot -Recurse -Force -ErrorAction SilentlyContinue
            }
        }
        $result | Should -Be $false
    }

    It "Logs ERROR and returns false when infrastructure template lacks supervisorServices.parentDirectory" {
        $result = InModuleScope VcfEdgeAtScale {
            $tmpRoot = Join-Path -Path ([System.IO.Path]::GetTempPath()) -ChildPath "veas-test-$([System.Guid]::NewGuid().ToString('N'))"
            $null = New-Item -ItemType Directory -Path $tmpRoot -Force
            try {
                $templatePath = Join-Path $tmpRoot "infra-template.json"
                # Template that has no supervisorServices.parentDirectory key.
                Set-Content -Path $templatePath -Value '{"common":{"foo":"bar"}}' -Encoding UTF8
                Mock Write-Host {}
                Mock Write-LogMessage {}
                Initialize-RootJsonFilesFromTemplate `
                    -BaseDirectory                 $tmpRoot `
                    -InfrastructureDestinationPath (Join-Path $tmpRoot "infrastructure.json") `
                    -InfrastructureTemplatePath    $templatePath `
                    -ServicesYamlDirectory         (Join-Path $tmpRoot "ServicesYaml") `
                    -SupervisorDestinationPath     (Join-Path $tmpRoot "supervisor.json") `
                    -SupervisorTemplatePath        (Join-Path $tmpRoot "missing-super-template.json") `
                    -TemplateRestoreHint           "reinstall hint"
            } finally {
                Remove-Item -LiteralPath $tmpRoot -Recurse -Force -ErrorAction SilentlyContinue
            }
        }
        $result | Should -Be $false
    }

    It "Returns true and writes both JSON files when both destination paths are absent" {
        $result = InModuleScope VcfEdgeAtScale {
            $tmpRoot = Join-Path -Path ([System.IO.Path]::GetTempPath()) -ChildPath "veas-test-$([System.Guid]::NewGuid().ToString('N'))"
            $null = New-Item -ItemType Directory -Path $tmpRoot -Force
            try {
                $infraTemplate = Join-Path $tmpRoot "infra-template.json"
                $superTemplate = Join-Path $tmpRoot "super-template.json"
                # Minimal valid infrastructure.json with the required parentDirectory placeholders.
                $infraJson = '{"common":{"supervisorServices":{"parentDirectory":"OLD_SVCS"}},"clusters":[{"harborConfiguration":{"parentDirectory":"OLD_BASE","hostname":"h.example.com"}}]}'
                Set-Content -Path $infraTemplate -Value $infraJson -Encoding UTF8
                Set-Content -Path $superTemplate -Value '{"version":1}' -Encoding UTF8
                Mock Write-Host {}
                Initialize-RootJsonFilesFromTemplate `
                    -BaseDirectory                 $tmpRoot `
                    -InfrastructureDestinationPath (Join-Path $tmpRoot "infrastructure.json") `
                    -InfrastructureTemplatePath    $infraTemplate `
                    -ServicesYamlDirectory         (Join-Path $tmpRoot "ServicesYaml") `
                    -SupervisorDestinationPath     (Join-Path $tmpRoot "supervisor.json") `
                    -SupervisorTemplatePath        $superTemplate `
                    -TemplateRestoreHint           "reinstall hint"
            } finally {
                Remove-Item -LiteralPath $tmpRoot -Recurse -Force -ErrorAction SilentlyContinue
            }
        }
        $result | Should -Be $true
    }

    It "Returns false and logs ERROR when supervisor.json template is missing" {
        $result = InModuleScope VcfEdgeAtScale {
            $tmpRoot = Join-Path -Path ([System.IO.Path]::GetTempPath()) -ChildPath "veas-test-$([System.Guid]::NewGuid().ToString('N'))"
            $null = New-Item -ItemType Directory -Path $tmpRoot -Force
            try {
                $infraTemplate = Join-Path $tmpRoot "infra-template.json"
                $infraJson = '{"common":{"supervisorServices":{"parentDirectory":"OLD_SVCS"}},"clusters":[{"harborConfiguration":{"parentDirectory":"OLD_BASE","hostname":"h.example.com"}}]}'
                Set-Content -Path $infraTemplate -Value $infraJson -Encoding UTF8
                Mock Write-Host {}
                Mock Write-LogMessage {}
                # Supervisor template is intentionally absent.
                Initialize-RootJsonFilesFromTemplate `
                    -BaseDirectory                 $tmpRoot `
                    -InfrastructureDestinationPath (Join-Path $tmpRoot "infrastructure.json") `
                    -InfrastructureTemplatePath    $infraTemplate `
                    -ServicesYamlDirectory         (Join-Path $tmpRoot "ServicesYaml") `
                    -SupervisorDestinationPath     (Join-Path $tmpRoot "supervisor.json") `
                    -SupervisorTemplatePath        (Join-Path $tmpRoot "missing-super-template.json") `
                    -TemplateRestoreHint           "reinstall hint"
            } finally {
                Remove-Item -LiteralPath $tmpRoot -Recurse -Force -ErrorAction SilentlyContinue
            }
        }
        $result | Should -Be $false
    }
}

# ── Invoke-PersistDeploymentRootDirectory ────────────────────────────────────

Describe "Invoke-PersistDeploymentRootDirectory — env var and profile persistence" {

    It "Sets VcfEdgeAtScaleRootDirectory to ResolvedBaseDirectory for the current session" {
        InModuleScope VcfEdgeAtScale {
            $savedEnv = $env:VcfEdgeAtScaleRootDirectory
            Mock Write-Host {}
            $createdList = [System.Collections.Generic.List[String]]::new()
            try {
                Invoke-PersistDeploymentRootDirectory `
                    -BaseDirectoryWasCreated $false `
                    -ResolvedBaseDirectory   "/test/base" `
                    -SubdirectoriesCreated   $createdList
                $env:VcfEdgeAtScaleRootDirectory | Should -Be "/test/base"
            } finally {
                $env:VcfEdgeAtScaleRootDirectory = $savedEnv
            }
        }
    }

    It "Creates PROFILE and appends env var assignment when PROFILE does not yet exist" {
        InModuleScope VcfEdgeAtScale {
            $savedEnv  = $env:VcfEdgeAtScaleRootDirectory
            $savedProf = $PROFILE
            $tmpProfile = Join-Path ([System.IO.Path]::GetTempPath()) "veas-profile-$([System.Guid]::NewGuid().ToString('N')).ps1"
            $createdList = [System.Collections.Generic.List[String]]::new()
            Mock Write-Host {}
            try {
                Set-Variable -Name PROFILE -Value $tmpProfile -Scope Script
                { Invoke-PersistDeploymentRootDirectory `
                    -BaseDirectoryWasCreated $false `
                    -ResolvedBaseDirectory   "/test/base" `
                    -SubdirectoriesCreated   $createdList } | Should -Not -Throw
                (Test-Path $tmpProfile) | Should -Be $true
            } finally {
                $env:VcfEdgeAtScaleRootDirectory = $savedEnv
                Set-Variable -Name PROFILE -Value $savedProf -Scope Script
                if (Test-Path $tmpProfile) { Remove-Item -LiteralPath $tmpProfile -Force -ErrorAction SilentlyContinue }
            }
        }
    }

    It "Does not append to PROFILE when ENV_VAR_NAME is already present" {
        InModuleScope VcfEdgeAtScale {
            $savedEnv  = $env:VcfEdgeAtScaleRootDirectory
            $savedProf = $PROFILE
            $tmpProfile = Join-Path ([System.IO.Path]::GetTempPath()) "veas-profile-$([System.Guid]::NewGuid().ToString('N')).ps1"
            $createdList = [System.Collections.Generic.List[String]]::new()
            Mock Write-Host {}
            try {
                # Pre-seed the profile with the env var assignment so the function should skip appending.
                Set-Content -Path $tmpProfile -Value "`$env:VcfEdgeAtScaleRootDirectory = `"/old/path`"" -Encoding UTF8
                Set-Variable -Name PROFILE -Value $tmpProfile -Scope Script
                Invoke-PersistDeploymentRootDirectory `
                    -BaseDirectoryWasCreated $false `
                    -ResolvedBaseDirectory   "/test/base" `
                    -SubdirectoriesCreated   $createdList
                $content = Get-Content -LiteralPath $tmpProfile -Raw
                # File should contain exactly one occurrence of the env var name — the one we seeded.
                ($content -split "VcfEdgeAtScaleRootDirectory").Count | Should -Be 2
            } finally {
                $env:VcfEdgeAtScaleRootDirectory = $savedEnv
                Set-Variable -Name PROFILE -Value $savedProf -Scope Script
                if (Test-Path $tmpProfile) { Remove-Item -LiteralPath $tmpProfile -Force -ErrorAction SilentlyContinue }
            }
        }
    }
}

# ── Invoke-WitnessFaultDomainSetup — fault domain resolution and stretched cluster activation ──

Describe "Invoke-WitnessFaultDomainSetup — Set-VsanClusterConfiguration call paths" {

    It "Calls Set-VsanClusterConfiguration once when fault domain is resolved" {
        $callCount = InModuleScope VcfEdgeAtScale {
            $Script:vCenterName = "vc.lab"
            $Script:_setVsanCount = 0
            $fakeWitnessHost = [PSCustomObject]@{ Name = "witness.lab" }
            function Get-VsanClusterConfiguration {
                [CmdletBinding()] Param([Parameter()] [Object]$Cluster, [Parameter()] [Object]$Server)
                [PSCustomObject]@{ WitnessHost = $fakeWitnessHost }
            }
            function Set-VsanClusterConfiguration {
                [CmdletBinding(SupportsShouldProcess = $true)]
                Param(
                    [Parameter()] [Object]$Configuration, [Parameter()] [Object]$WitnessHost,
                    [Parameter()] [Object]$PreferredFaultDomain, [Parameter()] [Switch]$StretchedClusterEnabled,
                    [Parameter()] [Object]$Server
                )
                begin { $Script:_setVsanCount++ }
                process {}
            }
            Mock Write-LogMessage {}
            Mock Write-Progress {}
            Mock Resolve-VsanPreferredFaultDomain { [PSCustomObject]@{ Name = "Primary" } }
            Mock Enable-VsanAutomaticDiskClaimIfSupported { $false }
            Mock Enable-VsanAutomaticRebalance { $false }
            Mock Test-VsanAutomaticRebalanceAtThreshold { $true }
            Mock Invoke-VsanClusterConfigReapply { $false }
            Mock Get-VsanClusterHealthSummaryViaView { $null }
            Invoke-WitnessFaultDomainSetup `
                -Cluster ([PSCustomObject]@{ Name = "cl01" }) `
                -ClusterHosts @([PSCustomObject]@{ Name = "esx01"; Id = "host-1" }) `
                -ClusterName "cl01" `
                -PreferredFaultDomainName "Primary" `
                -PreferredHost ([PSCustomObject]@{ Name = "esx01" }) `
                -VsanClusterConfig ([PSCustomObject]@{ WitnessHost = $null }) `
                -vSanWitnessVmName "witness.lab" `
                -WitnessHost $fakeWitnessHost
            $Script:_setVsanCount
        }
        $callCount | Should -Be 1
    }

    It "Logs a WARNING and still calls Set-VsanClusterConfiguration when preferred fault domain is null" {
        $warnCount = InModuleScope VcfEdgeAtScale {
            $Script:vCenterName = "vc.lab"
            $Script:_warnCount = 0
            $fakeWitnessHost = [PSCustomObject]@{ Name = "witness.lab" }
            function Get-VsanClusterConfiguration {
                [CmdletBinding()] Param([Parameter()] [Object]$Cluster, [Parameter()] [Object]$Server)
                [PSCustomObject]@{ WitnessHost = $fakeWitnessHost }
            }
            function Set-VsanClusterConfiguration {
                [CmdletBinding(SupportsShouldProcess = $true)]
                Param(
                    [Parameter()] [Object]$Configuration, [Parameter()] [Object]$WitnessHost,
                    [Parameter()] [Object]$PreferredFaultDomain, [Parameter()] [Switch]$StretchedClusterEnabled,
                    [Parameter()] [Object]$Server
                )
                begin {}; process {}
            }
            Mock Write-LogMessage { if ($Type -eq "WARNING") { $Script:_warnCount++ } }
            Mock Write-Progress {}
            Mock Resolve-VsanPreferredFaultDomain { $null }
            Mock Enable-VsanAutomaticDiskClaimIfSupported { $false }
            Mock Enable-VsanAutomaticRebalance { $false }
            Mock Test-VsanAutomaticRebalanceAtThreshold { $true }
            Mock Invoke-VsanClusterConfigReapply { $false }
            Mock Get-VsanClusterHealthSummaryViaView { $null }
            Invoke-WitnessFaultDomainSetup `
                -Cluster ([PSCustomObject]@{ Name = "cl01" }) `
                -ClusterHosts @([PSCustomObject]@{ Name = "esx01"; Id = "host-1" }) `
                -ClusterName "cl01" `
                -PreferredFaultDomainName "unknown-domain" `
                -PreferredHost ([PSCustomObject]@{ Name = "esx01" }) `
                -VsanClusterConfig ([PSCustomObject]@{ WitnessHost = $null }) `
                -vSanWitnessVmName "witness.lab" `
                -WitnessHost $fakeWitnessHost
            $Script:_warnCount
        }
        $warnCount | Should -BeGreaterOrEqual 1
    }

    It "Re-fetches VsanClusterConfiguration when Enable-VsanAutomaticDiskClaimIfSupported returns true" {
        $fetchCount = InModuleScope VcfEdgeAtScale {
            $Script:vCenterName = "vc.lab"
            $Script:_getConfigCount = 0
            $fakeWitnessHost = [PSCustomObject]@{ Name = "witness.lab" }
            function Get-VsanClusterConfiguration {
                [CmdletBinding()] Param([Parameter()] [Object]$Cluster, [Parameter()] [Object]$Server)
                $Script:_getConfigCount++
                [PSCustomObject]@{ WitnessHost = $fakeWitnessHost }
            }
            function Set-VsanClusterConfiguration {
                [CmdletBinding(SupportsShouldProcess = $true)]
                Param(
                    [Parameter()] [Object]$Configuration, [Parameter()] [Object]$WitnessHost,
                    [Parameter()] [Object]$PreferredFaultDomain, [Parameter()] [Switch]$StretchedClusterEnabled,
                    [Parameter()] [Object]$Server
                )
                begin {}; process {}
            }
            Mock Write-LogMessage {}
            Mock Write-Progress {}
            Mock Resolve-VsanPreferredFaultDomain { [PSCustomObject]@{ Name = "Primary" } }
            # Returning $true triggers the re-fetch path inside Invoke-WitnessFaultDomainSetup.
            Mock Enable-VsanAutomaticDiskClaimIfSupported { $true }
            Mock Enable-VsanAutomaticRebalance { $false }
            Mock Test-VsanAutomaticRebalanceAtThreshold { $true }
            Mock Invoke-VsanClusterConfigReapply { $false }
            Mock Get-VsanClusterHealthSummaryViaView { $null }
            Invoke-WitnessFaultDomainSetup `
                -Cluster ([PSCustomObject]@{ Name = "cl01" }) `
                -ClusterHosts @([PSCustomObject]@{ Name = "esx01"; Id = "host-1" }) `
                -ClusterName "cl01" `
                -PreferredFaultDomainName "Primary" `
                -PreferredHost ([PSCustomObject]@{ Name = "esx01" }) `
                -VsanClusterConfig ([PSCustomObject]@{ WitnessHost = $null }) `
                -vSanWitnessVmName "witness.lab" `
                -WitnessHost $fakeWitnessHost
            $Script:_getConfigCount
        }
        # One call for the re-fetch after Enable-VsanAutomaticDiskClaimIfSupported, one for post-config verification.
        $fetchCount | Should -BeGreaterOrEqual 2
    }

    # Regression guard: vSAN ESA witness join fails silently if Set-VsanClusterConfiguration is
    # not called when Enable-VsanAutomaticDiskClaimIfSupported returns $false. This test ensures
    # the witness configuration API call proceeds even on the degradation path.
    It "Calls Set-VsanClusterConfiguration with StretchedClusterEnabled even when Enable-VsanAutomaticDiskClaimIfSupported returns false (VsanDiskClaimMode unsupported degradation path)" {
        $setVsanCallCount = InModuleScope VcfEdgeAtScale {
            $Script:vCenterName = "vc.lab"
            $Script:_setVsanDegradedCount = 0
            $fakeWitnessHost = [PSCustomObject]@{ Name = "witness.lab" }
            function Get-VsanClusterConfiguration {
                [CmdletBinding()] Param([Parameter()] [Object]$Cluster, [Parameter()] [Object]$Server)
                [PSCustomObject]@{ WitnessHost = $fakeWitnessHost }
            }
            function Set-VsanClusterConfiguration {
                [CmdletBinding(SupportsShouldProcess = $true)]
                Param(
                    [Parameter()] [Object]$Configuration, [Parameter()] [Object]$WitnessHost,
                    [Parameter()] [Object]$PreferredFaultDomain, [Parameter()] [Switch]$StretchedClusterEnabled,
                    [Parameter()] [Object]$Server
                )
                begin { $Script:_setVsanDegradedCount++ }
                process {}
            }
            Mock Write-LogMessage {}
            Mock Write-Progress {}
            Mock Resolve-VsanPreferredFaultDomain { [PSCustomObject]@{ Name = "Primary" } }
            # VsanDiskClaimMode is NOT supported — returns $false (the degradation path).
            Mock Enable-VsanAutomaticDiskClaimIfSupported { $false }
            Mock Enable-VsanAutomaticRebalance { $false }
            Mock Test-VsanAutomaticRebalanceAtThreshold { $true }
            Mock Invoke-VsanClusterConfigReapply { $false }
            Mock Get-VsanClusterHealthSummaryViaView { $null }
            Invoke-WitnessFaultDomainSetup `
                -Cluster ([PSCustomObject]@{ Name = "cl01" }) `
                -ClusterHosts @([PSCustomObject]@{ Name = "esx01"; Id = "host-1" }) `
                -ClusterName "cl01" `
                -PreferredFaultDomainName "Primary" `
                -PreferredHost ([PSCustomObject]@{ Name = "esx01" }) `
                -VsanClusterConfig ([PSCustomObject]@{ WitnessHost = $null }) `
                -vSanWitnessVmName "witness.lab" `
                -WitnessHost $fakeWitnessHost
            $Script:_setVsanDegradedCount
        }
        # Set-VsanClusterConfiguration MUST be called even when disk-claim-mode is unsupported.
        $setVsanCallCount | Should -BeGreaterOrEqual 1
    }
}

