    It "Logs INFO and skips creation when the tag catalog already exists" {
        InModuleScope VcfEdgeAtScale {
            Mock Write-LogMessage {}
            Mock Test-VcenterConnection { [PSCustomObject]@{ IsConnected = $true } }
