# ── Test-TcpPortReachable ─────────────────────────────────────────────────────

Describe "Test-TcpPortReachable" {

    It "Returns false for a host that is not listening (timeout)" {
        # Port 1 on 127.0.0.1 is almost never open; a very short timeout ensures the test completes quickly.
        $result = InModuleScope VcfEdgeAtScale {
            Test-TcpPortReachable -IpAddress "127.0.0.1" -Port 1 -TimeoutMilliseconds 100
        }
        $result | Should -Be $false
    }

    It "Returns false for an invalid (non-routable) IP address" {
        $result = InModuleScope VcfEdgeAtScale {
            Test-TcpPortReachable -IpAddress "192.0.2.1" -Port 443 -TimeoutMilliseconds 200
        }
        $result | Should -Be $false
    }

    It "Returns $false and never throws for an unreachable host" {
        $result = InModuleScope VcfEdgeAtScale {
            Test-TcpPortReachable -IpAddress "not-a-real-host" -Port 9999 -TimeoutMilliseconds 100
        }
        { InModuleScope VcfEdgeAtScale {
            Test-TcpPortReachable -IpAddress "not-a-real-host" -Port 9999 -TimeoutMilliseconds 100
        } } | Should -Not -Throw
        $result | Should -Be $false
    }
}

# ── Read-VcfEdgeAtScaleManifestVersion ────────────────────────────────────────

Describe "Read-VcfEdgeAtScaleManifestVersion" {

    It "Returns 'unknown' and emits a Warning when the manifest file does not exist" {
        # Read-VcfEdgeAtScaleManifestVersion is removed from the Function: drive after module init.
        # We re-define it inside InModuleScope to exercise the error-path contract.
        $result = InModuleScope VcfEdgeAtScale {
            function Read-VcfEdgeAtScaleManifestVersion {
                [CmdletBinding()] [OutputType([String])] Param(
                    [Parameter(Mandatory = $true)] [ValidateNotNullOrEmpty()] [String]$ManifestPath
                )
                try {
                    # -ErrorAction Stop converts non-terminating file-not-found into a catchable exception.
                    return (Import-PowerShellDataFile -Path $ManifestPath -ErrorAction Stop).ModuleVersion
                } catch {
                    Write-Warning "VcfEdgeAtScale: Could not read module version from '$ManifestPath' — $($_.Exception.Message). Version will be reported as 'unknown'."
                    return "unknown"
                }
            }
            Read-VcfEdgeAtScaleManifestVersion -ManifestPath "/nonexistent/VcfEdgeAtScale.psd1"
        }
        $result | Should -Be "unknown"
    }

    It "Returns the version string from a valid manifest" {
        $tmpPsd1 = Join-Path ([System.IO.Path]::GetTempPath()) ("veas-test-{0}.psd1" -f [System.Guid]::NewGuid().ToString("N").Substring(0, 8))
        try {
            "@{ ModuleVersion = '9.8.7.6' }" | Set-Content -Path $tmpPsd1 -Encoding UTF8
            $result = InModuleScope VcfEdgeAtScale -ArgumentList $tmpPsd1 {
                function Read-VcfEdgeAtScaleManifestVersion {
                    [CmdletBinding()] [OutputType([String])] Param(
                        [Parameter(Mandatory = $true)] [ValidateNotNullOrEmpty()] [String]$ManifestPath
                    )
                    try { return (Import-PowerShellDataFile -Path $ManifestPath -ErrorAction Stop).ModuleVersion }
                    catch {
                        Write-Warning "VcfEdgeAtScale: Could not read module version from '$ManifestPath' — $($_.Exception.Message). Version will be reported as 'unknown'."
                        return "unknown"
                    }
                }
                Read-VcfEdgeAtScaleManifestVersion -ManifestPath $args[0]
            }
            $result | Should -Be "9.8.7.6"
        } finally {
            Remove-Item $tmpPsd1 -Force -ErrorAction SilentlyContinue
        }
    }
}

# ── Invoke-VcenterConnectionWithRetry ────────────────────────────────────────

Describe "Invoke-VcenterConnectionWithRetry" {
    It "Returns without throwing when Connect-VIServer succeeds on the first attempt" {
        InModuleScope VcfEdgeAtScale {
            function Connect-VIServer {
                [CmdletBinding()] Param([Parameter()] [Object]$Server, [Parameter()] [Object]$Credential)
                process {}
            }
            Mock Write-LogMessage {}
            Mock Connect-VIServer { [PSCustomObject]@{ Name = "vc.lab" } }
            $cred = [PSCredential]::new("admin", (ConvertTo-SecureString "pw" -AsPlainText -Force))
            { Invoke-VcenterConnectionWithRetry -CurrentCredential $cred -ServerName "vc.lab" -ServerType "vCenter" -SkipRetryPrompt } | Should -Not -Throw
            Should -Invoke Write-LogMessage -ParameterFilter { $Type -eq "DEBUG" -and $Message -match "Successfully connected" }
        }
    }

    It "Throws VcfDeploymentException immediately when Connect-VIServer raises an SSL error" {
        $exTypeName = InModuleScope VcfEdgeAtScale {
            function Connect-VIServer {
                [CmdletBinding()] Param([Parameter()] [Object]$Server, [Parameter()] [Object]$Credential)
                process {}
            }
            Mock Write-LogMessage {}
            Mock Connect-VIServer { throw "SSL connection could not be established" }
            $cred = [PSCredential]::new("admin", (ConvertTo-SecureString "pw" -AsPlainText -Force))
            try {
                Invoke-VcenterConnectionWithRetry -CurrentCredential $cred -ServerName "vc.lab" -ServerType "vCenter" -SkipRetryPrompt
                return "no-throw"
            } catch {
                return $_.Exception.GetType().Name
            }
        }
        $exTypeName | Should -Be "VcfDeploymentException"
    }

    It "Throws an exception matching 'Authentication failed' when auth fails with -SkipRetryPrompt" {
        $errorMsg = InModuleScope VcfEdgeAtScale {
            function Connect-VIServer {
                [CmdletBinding()] Param([Parameter()] [Object]$Server, [Parameter()] [Object]$Credential)
                process {}
            }
            Mock Write-LogMessage {}
            Mock Connect-VIServer { throw "incorrect user name or password" }
            $cred = [PSCredential]::new("admin", (ConvertTo-SecureString "pw" -AsPlainText -Force))
            try {
                Invoke-VcenterConnectionWithRetry -CurrentCredential $cred -ServerName "vc.lab" -ServerType "vCenter" -SkipRetryPrompt
                return "no-throw"
            } catch {
                return $_.Exception.Message
            }
        }
        $errorMsg | Should -Match "Authentication failed"
    }
}

